using System.Text.Json;

namespace UI_Desktop.Store;

internal static class StoreWarpOnboardingHtml
{
	internal static string Markup => "<div class=\"warp-welcome\" data-warp-welcome hidden>\n    <section class=\"warp-welcome-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"warpWelcomeTitle\" aria-describedby=\"warpWelcomeMessage\">\n        <button type=\"button\" class=\"warp-help-close\" data-warp-dismiss aria-label=\"Đóng thông báo VPN\">×</button>\n        <span class=\"warp-help-kicker\">KẾT NỐI STEAM</span>\n        <h2 id=\"warpWelcomeTitle\">Bật VPN hoặc 1.1.1.1</h2>\n        <p id=\"warpWelcomeMessage\">Bạn hãy bật VPN hoặc 1.1.1.1. Nếu không bật thì Steam luôn luôn không kết nối được mạng.</p>\n        <p class=\"warp-help-detail\" data-warp-welcome-detail></p>\n        <p class=\"warp-help-optional\">Bạn có thể bỏ qua và tiếp tục sử dụng launcher. Nếu đã dùng VPN khác, hãy chọn “Để sau”.</p>\n        <div class=\"warp-help-actions\">\n            <button type=\"button\" class=\"warp-help-secondary\" data-warp-dismiss data-warp-later>Để sau</button>\n            <button type=\"button\" class=\"warp-help-primary\" data-warp-guide>Hướng dẫn bật</button>\n        </div>\n    </section>\n</div>\n<aside class=\"warp-guide\" data-warp-guide-panel hidden role=\"region\" aria-labelledby=\"warpGuideTitle\">\n    <span class=\"warp-guide-arrow\" data-warp-guide-arrow aria-hidden=\"true\"></span>\n    <button type=\"button\" class=\"warp-help-close\" data-warp-dismiss aria-label=\"Đóng hướng dẫn WARP\">×</button>\n    <span class=\"warp-help-kicker\">CLOUDFLARE 1.1.1.1</span>\n    <h3 id=\"warpGuideTitle\" data-warp-guide-title></h3>\n    <p data-warp-guide-copy role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p>\n    <button type=\"button\" class=\"warp-help-secondary\" data-warp-dismiss>Bỏ qua hướng dẫn</button>\n</aside>";

	internal static string Styles => ".warp-welcome[hidden], .warp-guide[hidden] { display: none !important; }\n.warp-welcome { position: fixed; inset: 0; z-index: 5450; display: grid; place-items: center; padding: 20px; background: rgba(2, 8, 14, .78); }\n.warp-welcome-card, .warp-guide { box-sizing: border-box; border: 1px solid #4b8cb0; border-radius: 12px; background: linear-gradient(155deg, #182f43, #0d1926); color: #f2f6fa; box-shadow: 0 16px 45px rgba(0,0,0,.45); font-family: \"Segoe UI\", sans-serif; }\n.warp-welcome-card { position: relative; width: min(500px, 100%); max-height: calc(100vh - 40px); overflow: auto; padding: 30px; }\n.warp-help-kicker { display: block; padding-right: 35px; color: #9cdbff; font-size: 12px; font-weight: 700; letter-spacing: .1em; }\n.warp-welcome h2 { margin: 12px 0 16px; font-size: 25px; line-height: 1.25; }\n.warp-welcome p, .warp-guide p { font-size: 15px; line-height: 1.6; }\n.warp-welcome .warp-help-detail { color: #c9e8fa; }\n.warp-welcome .warp-help-optional { color: #c0ccd7; font-size: 13px; }\n.warp-help-close { position: absolute; top: 8px; right: 8px; width: 44px; height: 44px; border: 0; border-radius: 7px; background: transparent; color: #dbe8f3; font-size: 25px; cursor: pointer; }\n.warp-help-close:hover { background: #ffffff15; }\n.warp-help-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 12px; margin-top: 24px; }\n.warp-help-primary, .warp-help-secondary { min-height: 44px; padding: 10px 17px; border: 1px solid #567085; border-radius: 7px; color: #f2f6fa; background: #253b4d; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; }\n.warp-help-primary { color: #081622; background: #91d7fa; border-color: #91d7fa; }\n.warp-welcome button:focus-visible, .warp-guide button:focus-visible { outline: 2px solid #a3e1ff; outline-offset: 3px; }\n.warp-guide { position: fixed; z-index: 5450; width: min(340px, calc(100vw - 24px)); max-height: calc(100vh - 24px); overflow: auto; padding: 23px; }\n.warp-guide h3 { margin: 12px 0 8px; padding-right: 20px; font-size: 19px; }\n.warp-guide p { margin: 0 0 16px; }\n.warp-guide-arrow { position: fixed; width: 12px; height: 12px; background: #182f43; border-left: 1px solid #4b8cb0; border-top: 1px solid #4b8cb0; transform: rotate(45deg); }\n.warp-guide-arrow[hidden] { display: none; }\n.nestg-warp-control.warp-guide-anchor { outline: 2px solid #a3e1ff; outline-offset: 5px; border-radius: 7px; background: #1a3850; }\n.warp-welcome-card, .warp-guide { animation: warp-help-enter .16s ease-out; }\n.warp-guide { animation-name: warp-help-fade; }\n@keyframes warp-help-enter { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }\n@keyframes warp-help-fade { from { opacity: 0; } to { opacity: 1; } }\n@media (max-height: 430px), (max-width: 520px) { .warp-welcome-card { padding: 22px; } .warp-welcome h2 { font-size: 22px; } }\n@media (prefers-reduced-motion: reduce) { .warp-welcome-card, .warp-guide { animation: none; } }";

	internal static string BuildScript(string documentId)
	{
		return "(() => {\n    const documentId = " + JsonSerializer.Serialize(documentId) + ";\n    const welcome = document.querySelector('[data-warp-welcome]');\n    const guide = document.querySelector('[data-warp-guide-panel]');\n    const control = document.querySelector('[data-warp-control]');\n    if (!welcome || !guide || !control) return;\n    const app = document.querySelector('.app-shell');\n    const arrow = guide.querySelector('[data-warp-guide-arrow]');\n    const guideTitle = guide.querySelector('[data-warp-guide-title]');\n    const guideCopy = guide.querySelector('[data-warp-guide-copy]');\n    const detail = welcome.querySelector('[data-warp-welcome-detail]');\n    let state = null, dismissed = false, guideStarted = false, visibleMode = '', frame = 0, previousFocus = null;\n    let ownsInert = false, previousInert = false;\n    const post = type => window.chrome?.webview?.postMessage({ type, documentId });\n    const hide = (element, value) => { if (element.hidden !== value) element.hidden = value; };\n    const text = (element, value) => { if (element.textContent !== value) element.textContent = value; };\n    const visible = element => Boolean(element && !element.closest('[hidden]') && element.getClientRects().length && getComputedStyle(element).visibility !== 'hidden');\n    const blocked = () => Array.from(document.querySelectorAll('[role=\"dialog\"], [aria-modal=\"true\"]'))\n        .some(element => !welcome.contains(element) && visible(element));\n    const releaseInert = () => { if (app && ownsInert) { app.inert = previousInert; ownsInert = false; } };\n    const closeView = (restoreFocus = false) => {\n        const wasVisible = visibleMode;\n        hide(welcome, true); hide(guide, true); hide(arrow, true);\n        control.classList.remove('warp-guide-anchor');\n        releaseInert();\n        visibleMode = '';\n        if (restoreFocus && wasVisible && previousFocus?.isConnected && !blocked()) previousFocus.focus();\n    };\n    const dismiss = () => {\n        if (dismissed) return;\n        dismissed = true;\n        closeView(true);\n        stopWatching();\n        post('dismissWarpOnboarding');\n    };\n    const target = () => state?.kind === 'NotInstalled'\n        ? control.querySelector('[data-warp-install]') : control.querySelector('[data-warp-switch]');\n    const positionGuide = () => {\n        if (guide.hidden) return;\n        const anchor = control.getBoundingClientRect();\n        const width = guide.offsetWidth, height = guide.offsetHeight;\n        const left = Math.max(12, Math.min(innerWidth - width - 12, anchor.left));\n        const top = Math.max(12, Math.min(innerHeight - height - 12, anchor.bottom + 15));\n        const setPixel = (element, name, value) => {\n            const pixel = Math.round(value) + 'px';\n            if (element.style[name] !== pixel) element.style[name] = pixel;\n        };\n        setPixel(guide, 'left', left); setPixel(guide, 'top', top);\n        hide(arrow, top < anchor.bottom + 10);\n        setPixel(arrow, 'left', Math.max(left + 22, Math.min(left + width - 28, anchor.left + anchor.width / 2 - 6)));\n        setPixel(arrow, 'top', top - 6);\n    };\n    const render = () => {\n        if (state && ['Completed', 'Dismissed'].includes(state.phase)) {\n            dismissed = true; closeView(true); stopWatching(); return;\n        }\n        if (!state || dismissed || ['Pending', 'Completed', 'Dismissed'].includes(state.phase)) {\n            closeView(true); return;\n        }\n        if (state.busy || state.kind === 'Connecting' || blocked()) { closeView(); return; }\n        const mode = guideStarted || state.phase === 'Guiding' ? 'guide' : 'welcome';\n        if (!visibleMode) previousFocus = document.activeElement;\n        if (mode === 'welcome') {\n            text(detail, state.kind === 'NotInstalled'\n                ? 'Chọn “Hướng dẫn bật” để tìm nút Cài WARP trên thanh trên cùng, cạnh logo NestG.'\n                : state.kind === 'Disconnected'\n                    ? 'Bạn có thể bật Cloudflare WARP bằng công tắc trên thanh trên cùng, cạnh logo NestG.'\n                    : state.detail || 'Hãy kiểm tra chế độ WARP trong ứng dụng Cloudflare.');\n            hide(guide, true); hide(welcome, false);\n            if (app && !ownsInert) { previousInert = app.inert; app.inert = true; ownsInert = true; }\n            if (visibleMode !== mode) welcome.querySelector('[data-warp-later]').focus();\n        } else {\n            hide(welcome, true);\n            releaseInert();\n            const canUseSwitch = state.canToggle && state.kind === 'Disconnected';\n            text(guideTitle, state.kind === 'NotInstalled' ? 'Cài WARP tại đây' : canUseSwitch ? 'Bật WARP tại đây' : 'Kiểm tra Cloudflare WARP');\n            text(guideCopy, state.kind === 'NotInstalled'\n                ? 'Bấm “Cài WARP” ở vùng được đánh dấu. Cài xong, quay lại bật công tắc WARP.'\n                : canUseSwitch\n                    ? (state.detail && state.unconfirmed ? state.detail : 'Bấm công tắc WARP ở vùng được đánh dấu. Hướng dẫn sẽ kết thúc khi kết nối được xác nhận.')\n                    : state.detail || 'Mở ứng dụng Cloudflare để kiểm tra kết nối và chuyển sang chế độ WARP.');\n            hide(guide, false);\n            control.classList.add('warp-guide-anchor');\n            positionGuide();\n            if (visibleMode !== mode) {\n                const button = target();\n                (button && !button.disabled && visible(button) ? button : guide.querySelector('[data-warp-dismiss]')).focus();\n            }\n        }\n        visibleMode = mode;\n    };\n    const schedule = () => { if (!frame) frame = requestAnimationFrame(() => { frame = 0; render(); }); };\n    welcome.querySelector('[data-warp-guide]').addEventListener('click', () => {\n        guideStarted = true; post('startWarpOnboarding'); render();\n    });\n    document.querySelectorAll('[data-warp-dismiss]').forEach(button => button.addEventListener('click', dismiss));\n    const onKey = event => {\n        if (!visibleMode) return;\n        if (event.key === 'Escape') { event.preventDefault(); event.stopImmediatePropagation(); dismiss(); return; }\n        if (event.key !== 'Tab' || visibleMode !== 'welcome') return;\n        const buttons = Array.from(welcome.querySelectorAll('button')).filter(button => !button.disabled && visible(button));\n        const index = buttons.indexOf(document.activeElement);\n        event.preventDefault(); event.stopImmediatePropagation();\n        buttons[(index + (event.shiftKey ? -1 : 1) + buttons.length) % buttons.length]?.focus();\n    };\n    document.addEventListener('keydown', onKey, true);\n    const observer = new MutationObserver(records => {\n        if (records.some(record => !welcome.contains(record.target) && !guide.contains(record.target) && record.target !== control)) schedule();\n    });\n    observer.observe(document.body, { subtree: true, attributes: true, attributeFilter: ['hidden', 'class', 'style', 'aria-hidden'] });\n    const resize = new ResizeObserver(schedule);\n    resize.observe(control); resize.observe(guide);\n    window.addEventListener('resize', schedule);\n    window.addEventListener('scroll', schedule, { passive: true });\n    const stopWatching = () => {\n        observer.disconnect(); resize.disconnect(); cancelAnimationFrame(frame);\n        frame = 0;\n        window.removeEventListener('resize', schedule); window.removeEventListener('scroll', schedule);\n        document.removeEventListener('keydown', onKey, true);\n    };\n    window.addEventListener('pagehide', () => { stopWatching(); closeView(); }, { once: true });\n    window.__nestgWarpOnboarding = {\n        documentId,\n        setState(next) { if (next?.documentId !== documentId) return; state = next; render(); }\n    };\n})();";
	}
}
